from __future__ import annotations

import uuid

from pydantic import BaseModel, Field

# Hard transport cap; the configurable MAX_MESSAGE_CHARS (smaller) is enforced by the chat service
# so the user gets a specific `message_too_long` error.
HARD_MAX_CHARS = 100_000


class SendMessageIn(BaseModel):
    # Generated by the client per message; makes resubmission idempotent.
    client_message_id: uuid.UUID
    content: str = Field(max_length=HARD_MAX_CHARS)
